  done < <(cd "$repo" && gh release list --limit 10 --json tagName --jq '.[].tagName' 2>/dev/null)
  if [ "${prev_n:-0}" -gt 0 ]; then
    # 자산은 릴리즈 워크플로가 붙인다 — 워크플로가 아직 돌고 있으면 계속 기다린다(이미지 빌드는 20분 넘기도 한다).
